using Microsoft.EntityFrameworkCore;
using WorkForce360.Api.Models;
namespace WorkForce360.Api.Data;
public class TripDbContext(DbContextOptions<TripDbContext> options):DbContext(options)
{
 public DbSet<TripUser> Users=>Set<TripUser>(); public DbSet<Tourist> Tourists=>Set<Tourist>(); public DbSet<TripRequest> TripRequests=>Set<TripRequest>(); public DbSet<Attraction> Attractions=>Set<Attraction>(); public DbSet<Itinerary> Itineraries=>Set<Itinerary>(); public DbSet<ItineraryDay> ItineraryDays=>Set<ItineraryDay>(); public DbSet<ItineraryStop> ItineraryStops=>Set<ItineraryStop>(); public DbSet<Guide> Guides=>Set<Guide>(); public DbSet<Vehicle> Vehicles=>Set<Vehicle>(); public DbSet<Hotel> Hotels=>Set<Hotel>(); public DbSet<RoomType> RoomTypes=>Set<RoomType>(); public DbSet<ResourceHold> ResourceHolds=>Set<ResourceHold>(); public DbSet<Quotation> Quotations=>Set<Quotation>(); public DbSet<QuotationLine> QuotationLines=>Set<QuotationLine>(); public DbSet<ApprovalDecision> ApprovalDecisions=>Set<ApprovalDecision>(); public DbSet<TripAuditLog> AuditLogs=>Set<TripAuditLog>();
 protected override void OnModelCreating(ModelBuilder b){b.Entity<TripUser>().HasIndex(x=>x.Email).IsUnique();b.Entity<Tourist>().HasIndex(x=>x.UserId).IsUnique();b.Entity<Guide>().HasIndex(x=>x.UserId).IsUnique();b.Entity<Vehicle>().HasIndex(x=>x.RegistrationNo).IsUnique();b.Entity<Attraction>().HasIndex(x=>x.City);b.Entity<Hotel>().HasIndex(x=>x.City);b.Entity<TripRequest>().HasIndex(x=>new{x.Status,x.StartDate});b.Entity<Itinerary>().HasIndex(x=>x.TripRequestId).IsUnique();b.Entity<ItineraryDay>().HasIndex(x=>new{x.ItineraryId,x.DayNumber}).IsUnique();b.Entity<ItineraryStop>().HasIndex(x=>new{x.ItineraryDayId,x.Sequence}).IsUnique();b.Entity<Quotation>().HasIndex(x=>new{x.TripRequestId,x.Version}).IsUnique();b.Entity<ResourceHold>().HasIndex(x=>new{x.ResourceType,x.ResourceId,x.FromDate,x.ToDate});b.Entity<TripRequest>().ToTable(t=>t.HasCheckConstraint("CK_Trip_Dates","\"EndDate\" >= \"StartDate\" AND \"Pax\" > 0 AND \"BudgetUsd\" > 0"));}
 public override Task<int> SaveChangesAsync(CancellationToken token=default){foreach(var e in ChangeTracker.Entries<TripEntity>().Where(x=>x.State==EntityState.Modified))e.Entity.UpdatedAt=DateTime.UtcNow;return base.SaveChangesAsync(token);}
}
